            perpDist = (float(mapPos.y) - pos.y + (1.0 - float(step.y)) * 0.5) / rayDir.y;
        }
        perpDist = max(perpDist, 0.0001);

        // Altura de la pared proyectada
        float lineHeight = uResolution.y / perpDist;
        float drawStart = max(-lineHeight / 2.0 + uResolution.y / 2.0, 0.0);
        float drawEnd   = min(lineHeight / 2.0 + uResolution.y / 2.0, uResolution.y);

        float screenY = vUV.y * uResolution.y;

        vec3 wCol = wallColor(wallType, sideHit);
        // Atenuación simple por distancia (niebla)
        float fog = clamp(1.0 - perpDist / 12.0, 0.15, 1.0);

        if (screenY < drawStart) {
            // Techo
            color = vec3(0.3, 0.3, 0.35);
        } else if (screenY > drawEnd) {
            // Suelo
            color = vec3(0.35, 0.3, 0.25);
        } else {
            color = wCol * fog;
        }
    } else {
        color = vec3(0.5, 0.6, 0.8); // Cielo de respaldo
    }

    FragColor = vec4(color, 1.0);
}
```

## Notas de implementación

- **Vertex shader**: trivial, solo dibuja un quad de pantalla completa y pasa las UV.
- **Fragment shader**: el trabajo real ocurre aquí. Por cada píxel (columna de pantalla), se:
  1. Calcula la dirección del rayo según el FOV y la posición del jugador.
  2. Aplica el algoritmo **DDA** (Digital Differential Analysis) para encontrar la primera pared golpeada en la cuadrícula del mapa.
  3. Calcula la distancia perpendicular corregida (evita el efecto ojo de pez).
  4. Proyecta la altura de la pared en pantalla y colorea techo/suelo/pared según corresponda.
- El mapa está **hardcodeado** como en los clásicos de los 90; se puede sustituir por una textura o buffer de datos si se desea cargar niveles dinámicamente.
- Se incluyó niebla simple y sombreado por cara para dar sensación de profundidad, típico de esos motores.
- La cámara se mueve automáticamente con `uTime`; en una aplicación real, `pos`, `dir` y `plane` vendrían de uniforms controlados por el input del usuario.

Este código es compatible con OpenGL 3.3+ / GLSL 330, y puede adaptarse fácilmente a WebGL (GLSL ES) cambiando la cabecera de versión y los arrays (WebGL 1 no soporta arrays de inicialización directa igual, requeriría pasarlos como uniforms o usar una textura de mapa).

