# JavaScript Function to Extract Text from a Document

"Document" can mean two things, so here are solutions for both:

1. **An HTML/DOM document** in the browser
2. **A file** such as `.txt`, `.pdf`, `.docx`, or `.html` in Node.js

---

## 1. Extract Text from an HTML Document (Browser)

The simplest option is:

```javascript
const text = document.body.innerText;
```

`innerText` is layout-aware, so it respects CSS and skips hidden elements. It can't be customized, though, and it doesn't work outside a rendered page (for example, in jsdom or on detached nodes). The function below gives you more control.

```javascript
/**
 * Extracts readable text from a DOM document or element.
 *
 * @param {Node} [root=document.body] - The node to extract text from.
 * @param {Object} [options]
 * @param {string[]} [options.skipTags] - Tags whose content should be ignored.
 * @param {boolean} [options.includeHidden=false] - Include elements hidden via CSS.
 * @returns {string} The extracted text.
 */
function extractText(root = document.body, options = {}) {
  const {
    skipTags = ['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'IFRAME', 'SVG', 'CANVAS'],
    includeHidden = false,
  } = options;

  const skip = new Set(skipTags.map(t => t.toUpperCase()));

  // Elements that should produce line breaks around their content
  const blockTags = new Set([
    'ADDRESS', 'ARTICLE', 'ASIDE', 'BLOCKQUOTE', 'DD', 'DIV', 'DL', 'DT',
    'FIELDSET', 'FIGCAPTION', 'FIGURE', 'FOOTER', 'FORM', 'H1', 'H2', 'H3',
    'H4', 'H5', 'H6', 'HEADER', 'HR', 'LI', 'MAIN', 'NAV', 'OL', 'P', 'PRE',
    'SECTION', 'TABLE', 'TR', 'UL',
  ]);

  const parts = [];

  function isHidden(el) {
    if (includeHidden || typeof window === 'undefined' || !window.getComputedStyle) {
      return false;
    }
    const style = window.getComputedStyle(el);
    return style.display === 'none' || style.visibility === 'hidden';
  }

  function walk(node) {
    if (node.nodeType === Node.TEXT_NODE) {
      // Collapse runs of whitespace like the browser does
      const value = node.nodeValue.replace(/\s+/g, ' ');
      if (value) parts.push(value);
      return;
    }

    if (node.nodeType === Node.ELEMENT_NODE) {
      const tag = node.tagName.toUpperCase();

      if (skip.has(tag) || isHidden(node)) return;

      if (tag === 'BR') {
        parts.push('\n');
        return;
      }

      // Include alt text for images
      if (tag === 'IMG' && node.alt) {
        parts.push(` ${node.alt} `);
        return;
      }

      // Include form field values
      if ((tag === 'INPUT' || tag === 'TEXTAREA') && node.value) {
        parts.push(` ${node.value} `);
        return;
      }

      const isBlock = blockTags.has(tag);
      if (isBlock) parts.push('\n');

      // Separate table cells with tabs
      if (tag === 'TD' || tag === 'TH') parts.push('\t');

      for (const child of node.childNodes) walk(child);

      if (isBlock) parts.push('\n');
      return;
    }

    // Document or DocumentFragment: walk the children
    if (
      node.nodeType === Node.DOCUMENT_NODE ||
      node.nodeType === Node.DOCUMENT_FRAGMENT_NODE
    ) {
      for (const child of node.childNodes) walk(child);
    }
  }

  walk(root);

  return parts
    .join('')
    .replace(/[ \t]*\n[ \t]*/g, '\n') // Trim spaces around line breaks
    .replace(/[ ]{2,}/g, ' ')         // Collapse repeated spaces
    .replace(/\n{3,}/g, '\n\n')       // At most one blank line
    .trim();
}
```

### Usage

```javascript
// Entire page
console.log(extractText());

// A specific element
console.log(extractText(document.querySelector('article')));

// Include hidden elements and keep <svg> text
console.log(extractText(document.body, {
  includeHidden: true,
  skipTags: ['SCRIPT', 'STYLE'],
}));

// From an HTML string
const doc = new DOMParser().parseFromString('<p>Hello <b>world</b></p>', 'text/html');
console.log(extractText(doc.body)); // "Hello world"
```

---

## 2. Extract Text from Files (Node.js)

Install the libraries for the formats you need:

```bash
npm install pdf-parse@1 mammoth jsdom
```

```javascript
const fs = require('fs/promises');
const path = require('path');

/**
 * Extracts text from a file based on its extension.
 * Supports: .txt, .md, .csv, .json, .pdf, .docx, .html/.htm
 *
 * @param {string} filePath
 * @returns {Promise<string>}
 */
async function extractTextFromFile(filePath) {
  const ext = path.extname(filePath).toLowerCase();

  switch (ext) {
    case '.txt':
    case '.md':
    case '.csv':
    case '.json':
      return fs.readFile(filePath, 'utf8');

    case '.pdf': {
      const pdfParse = require('pdf-parse');
      const buffer = await fs.readFile(filePath);
      const data = await pdfParse(buffer);
      return data.text.trim();
    }

    case '.docx': {
      const mammoth = require('mammoth');
      const { value } = await mammoth.extractRawText({ path: filePath });
      return value.trim();
    }

    case '.html':
    case '.htm': {
      const { JSDOM } = require('jsdom');
      const html = await fs.readFile(filePath, 'utf8');
      const { document } = new JSDOM(html).window;
      document.querySelectorAll('script, style, noscript').forEach(el => el.remove());
      return document.body.textContent.replace(/\s+/g, ' ').trim();
    }

    default:
      throw new Error(`Unsupported file type: ${ext}`);
  }
}

// Usage
(async () => {
  try {
    const text = await extractTextFromFile('./example.pdf');
    console.log(text);
  } catch (err) {
    console.error('Failed to extract text:', err.message);
  }
})();
```

---

## Notes

| Scenario | Recommended approach |
|---|---|
| Quick text from a rendered web page | `document.body.innerText` |
| Custom rules (skip tags, hidden content, tables) | `extractText()` above |
| HTML string without a browser | `DOMParser` (browser) or `jsdom` (Node) |
| PDF | `pdf-parse` (Node) or `pdfjs-dist` (browser) |
| Word (.docx) | `mammoth` |
| Scanned PDFs or images | OCR, such as `tesseract.js` |

- **Old `.doc` files** (not `.docx`) aren't supported by mammoth. Convert them first or use a tool like `textract`.
- **`pdf-parse` v2** changed its API. The code above uses v1 (`pdf-parse@1`).

