Below is a compact but functional **voxel terrain engine** for Godot 4 (GDScript), similar in spirit to Minecraft: chunked world, procedural terrain via noise, greedy-ish face culling (only visible faces are drawn), and a chunk manager that generates chunks around the player.

This is a solid foundation — not a full-feature clone, but a real working starting point you can extend (lighting, saving, block placing, etc).

## Project structure
```
res://
  world.gd         (World/ChunkManager)
  chunk.gd         (Chunk - mesh generation)
  voxel_data.gd    (Block/material definitions)
  player.gd        (basic flying controller, optional)
```

---

### `voxel_data.gd`
```gdscript
extends Node
class_name VoxelData

enum BlockType { AIR, GRASS, DIRT, STONE, SAND, WATER }

const CHUNK_SIZE_X = 16
const CHUNK_SIZE_Y = 64
const CHUNK_SIZE_Z = 16

# Simple color per block type (used instead of textures for simplicity)
static func get_color(block: int) -> Color:
	match block:
		BlockType.GRASS: return Color(0.2, 0.8, 0.2)
		BlockType.DIRT:  return Color(0.5, 0.35, 0.2)
		BlockType.STONE: return Color(0.5, 0.5, 0.5)
		BlockType.SAND:  return Color(0.9, 0.85, 0.5)
		BlockType.WATER: return Color(0.2, 0.4, 0.9)
		_: return Color(1, 0, 1) # AIR shouldn't be rendered
```

---

### `chunk.gd`
```gdscript
extends StaticBody3D
class_name Chunk

var chunk_pos: Vector2i
var world: Node
var blocks := {} # Vector3i -> int (block type)

var mesh_instance: MeshInstance3D
var collision_shape: CollisionShape3D

func _init(_chunk_pos: Vector2i, _world: Node) -> void:
	chunk_pos = _chunk_pos
	world = _world

func _ready() -> void:
	mesh_instance = MeshInstance3D.new()
	add_child(mesh_instance)

	collision_shape = CollisionShape3D.new()
	add_child(collision_shape)

	generate_terrain()
	build_mesh()

func get_block(x: int, y: int, z: int) -> int:
	if y < 0 or y >= VoxelData.CHUNK_SIZE_Y:
		return VoxelData.BlockType.AIR
	var key = Vector3i(x, y, z)
	if blocks.has(key):
		return blocks[key]
	return VoxelData.BlockType.AIR

func set_block(x: int, y: int, z: int, type: int) -> void:
	blocks[Vector3i(x, y, z)] = type

func generate_terrain() -> void:
	var noise := world.noise
	for x in range(VoxelData.CHUNK_SIZE_X):
		for z in range(VoxelData.CHUNK_SIZE_Z):
			var world_x = chunk_pos.x * VoxelData.CHUNK_SIZE_X + x
			var world_z = chunk_pos.y * VoxelData.CHUNK_SIZE_Z + z

			var height_val = noise.get_noise_2d(world_x, world_z)
			var height = int(20 + height_val * 15) # base height + variation
			height = clamp(height, 1, VoxelData.CHUNK_SIZE_Y - 1)

			for y in range(height):
				var type: int
				if y == height - 1:
					type = VoxelData.BlockType.GRASS
				elif y > height - 4:
					type = VoxelData.BlockType.DIRT
				else:
					type = VoxelData.BlockType.STONE
				set_block(x, y, z, type)

func build_mesh() -> void:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)

	for pos in blocks.keys():
		var block_type = blocks[pos]
		if block_type == VoxelData.BlockType.AIR:
			continue
		add_block_faces(st, pos, block_type)

	st.generate_normals()
	var mesh = st.commit()
	mesh_instance.mesh = mesh

	# Basic material (vertex colors)
	var mat := StandardMaterial3D.new()
	mat.vertex_color_use_as_albedo = true
	mesh_instance.material_override = mat

	# Collision
	if mesh.get_surface_count() > 0:
		var shape := mesh.create_trimesh_shape()
		collision_shape.shape = shape

# Directions: +X, -X, +Y, -Y, +Z, -Z
const DIRS = [
	Vector3i(1,0,0), Vector3i(-1,0,0),
	Vector3i(0,1,0), Vector3i(0,-1,0),
	Vector3i(0,0,1), Vector3i(0,0,-1)
]

func add_block_faces(st: SurfaceTool, pos: Vector3i, block_type: int) -> void:
	var color = VoxelData.get_color(block_type)

	for dir in DIRS:
		var neighbor = pos + dir
		var neighbor_block: int
		# Check within-chunk or neighbor chunk (simplified: treat outside as visible)
		if neighbor.x < 0 or neighbor.x >= VoxelData.CHUNK_SIZE_X \
		or neighbor.z < 0 or neighbor.z >= VoxelData.CHUNK_SIZE_Z:
			neighbor_block = VoxelData.BlockType.AIR # simplification (no chunk border culling)
		else:
			neighbor_block = get_block(neighbor.x, neighbor.y, neighbor.z)

		if neighbor_block == VoxelData.BlockType.AIR:
			add_face(st, pos, dir, color)

func add_face(st: SurfaceTool, pos: Vector3i, dir: Vector3i, color: Color) -> void:
	var p = Vector3(pos.x, pos.y, pos.z)
	var verts: Array
	var normal := Vector3(dir.x, dir.y, dir.z)

	# Define quad corners per direction (unit cube faces)
	if dir == Vector3i(1,0,0):
		verts = [p+Vector3(1,0,0), p+Vector3(1,1,0), p+Vector3(1,1,1), p+Vector3(1,0,1)]
	elif dir == Vector3i(-1,0,0):
		verts = [p+Vector3(0,0,1), p+Vector3(0,1,1), p+Vector3(0,1,0), p+Vector3(0,0,0)]
	elif dir == Vector3i(0,1,0):
		verts = [p+Vector3(0,1,0), p+Vector3(0,1,1), p+Vector3(1,1,1), p+Vector3(1,1,0)]
	elif dir == Vector3i(0,-1,0):
		verts = [p+Vector3(0,0,1), p+Vector3(0,0,0), p+Vector3(1,0,0), p+Vector3(1,0,1)]
	elif dir == Vector3i(0,0,1):
		verts = [p+Vector3(1,0,1), p+Vector3(1,1,1), p+Vector3(0,1,1), p+Vector3(0,0,1)]
	elif dir == Vector3i(0,0,-1):
		verts = [p+Vector3(0,0,0), p+Vector3(0,1,0), p+Vector3(1,1,0), p+Vector3(1,0,0)]

	# Two triangles per quad
	st.set_normal(normal)
	st.set_color(color)
	st.add_vertex(verts[0])
	st.set_color(color)
	st.add_vertex(verts[1])
	st.set_color(color)
	st.add_vertex(verts[2])

	st.set_color(color)
	st.add_vertex(verts[0])
	st.set_color(color)
	st.add_vertex(verts[2])
	st.set_color(color)
	st.add_vertex(verts[3])
```

---

### `world.gd`
```gdscript
extends Node3D
class_name World

@export var render_distance: int = 4
@export var player_path: NodePath

var noise := FastNoiseLite.new()
var chunks := {} # Vector2i -> Chunk
var player: Node3D

func _ready() -> void:
	noise.seed = randi()
	noise.frequency = 0.02

	if player_path:
		player = get_node(player_path)

	update_chunks()

func _process(_delta: float) -> void:
	if player:
		update_chunks()

func get_chunk_coord(world_pos: Vector3) -> Vector2i:
	return Vector2i(
		floor(world_pos.x / VoxelData.CHUNK_SIZE_X),
		floor(world_pos.z / VoxelData.CHUNK_SIZE_Z)
	)

func update_chunks() -> void:
	var center := Vector2i(0,0)
	if player:
		center = get_chunk_coord(player.global_transform.origin)

	var needed := {}
	for x in range(center.x - render_distance, center.x + render_distance + 1):
		for z in range(center.y - render_distance, center.y + render_distance + 1):
			var coord = Vector2i(x, z)
			needed[coord] = true
			if not chunks.has(coord):
				spawn_chunk(coord)

	# Remove far chunks
	for coord in chunks.keys():
		if not needed.has(coord):
			chunks[coord].queue_free()
			chunks.erase(coord)

func spawn_chunk(coord: Vector2i) -> void:
	var chunk := Chunk.new(coord, self)
	chunk.position = Vector3(coord.x * VoxelData.CHUNK_SIZE_X, 0, coord.y * VoxelData.CHUNK_SIZE_Z)
	add_child(chunk)
	chunks[coord] = chunk
```

---

### Basic scene setup
1. Create a `World.tscn` with a `Node3D` root, attach `world.gd`.
2. Add a `DirectionalLight3D` and a simple `Camera3D`/player controller (`CharacterBody3D`) that flies around; set `player_path` in the inspector.
3. Add `VoxelData` as an autoload (Project Settings → Autoload → name it `VoxelData`, point to `voxel_data.gd`) so `Chunk` can reference it as a global singleton constant class.

---

### Notes & possible improvements
- **Performance**: This naive per-block SurfaceTool approach is fine for small render distances; for real performance, use greedy meshing and multithreaded chunk generation (`Thread`/`WorkerThreadPool`).
- **Chunk borders**: Currently faces at chunk edges are always drawn (no neighbor-chunk lookups) — extend `get_block` to query neighboring `Chunk` objects from `world.chunks` for correct culling.
- **Block placing/breaking**: Use raycasts from the player camera, then call `chunk.set_block()` + `chunk.build_mesh()` to regenerate the mesh.
- **Textures**: Replace vertex colors with a texture atlas + UV mapping per block face for a truer Minecraft look.
- **Persistence**: Serialize `blocks` dictionary per chunk to disk for save/load.

This gives you a working voxel terrain with procedural hills, chunk streaming around the player, and collision — a good base to build a full Minecraft-like game on top of.

