### `chunk.gd`
```gdscript
extends StaticBody3D
class_name Chunk

var chunk_pos: Vector2i
var world: Node
var blocks := {} # Vector3i -> int (block type)

var mesh_instance: MeshInstance3D
var collision_shape: CollisionShape3D

func _init(_chunk_pos: Vector2i, _world: Node) -> void:
	chunk_pos = _chunk_pos
	world = _world

func _ready() -> void:
	mesh_instance = MeshInstance3D.new()
	add_child(mesh_instance)

	collision_shape = CollisionShape3D.new()
	add_child(collision_shape)

	generate_terrain()
	build_mesh()

func get_block(x: int, y: int, z: int) -> int:
	if y < 0 or y >= VoxelData.CHUNK_SIZE_Y:
		return VoxelData.BlockType.AIR
	var key = Vector3i(x, y, z)
	if blocks.has(key):
		return blocks[key]
	return VoxelData.BlockType.AIR

func set_block(x: int, y: int, z: int, type: int) -> void:
	blocks[Vector3i(x, y, z)] = type

func generate_terrain() -> void:
	var noise := world.noise
	for x in range(VoxelData.CHUNK_SIZE_X):
		for z in range(VoxelData.CHUNK_SIZE_Z):
			var world_x = chunk_pos.x * VoxelData.CHUNK_SIZE_X + x
			var world_z = chunk_pos.y * VoxelData.CHUNK_SIZE_Z + z

			var height_val = noise.get_noise_2d(world_x, world_z)
			var height = int(20 + height_val * 15) # base height + variation
			height = clamp(height, 1, VoxelData.CHUNK_SIZE_Y - 1)

			for y in range(height):
				var type: int
				if y == height - 1:
					type = VoxelData.BlockType.GRASS
				elif y > height - 4:
					type = VoxelData.BlockType.DIRT
				else:
					type = VoxelData.BlockType.STONE
				set_block(x, y, z, type)

func build_mesh() -> void:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)

	for pos in blocks.keys():
		var block_type = blocks[pos]
		if block_type == VoxelData.BlockType.AIR:
			continue
		add_block_faces(st, pos, block_type)

	st.generate_normals()
	var mesh = st.commit()
	mesh_instance.mesh = mesh

	# Basic material (vertex colors)
	var mat := StandardMaterial3D.new()
	mat.vertex_color_use_as_albedo = true
	mesh_instance.material_override = mat

	# Collision
	if mesh.get_surface_count() > 0:
		var shape := mesh.create_trimesh_shape()
		collision_shape.shape = shape

# Directions: +X, -X, +Y, -Y, +Z, -Z
const DIRS = [
	Vector3i(1,0,0), Vector3i(-1,0,0),
	Vector3i(0,1,0), Vector3i(0,-1,0),
	Vector3i(0,0,1), Vector3i(0,0,-1)
]

func add_block_faces(st: SurfaceTool, pos: Vector3i, block_type: int) -> void:
	var color = VoxelData.get_color(block_type)

	for dir in DIRS:
		var neighbor = pos + dir
		var neighbor_block: int
		# Check within-chunk or neighbor chunk (simplified: treat outside as visible)
		if neighbor.x < 0 or neighbor.x >= VoxelData.CHUNK_SIZE_X \
		or neighbor.z < 0 or neighbor.z >= VoxelData.CHUNK_SIZE_Z:
			neighbor_block = VoxelData.BlockType.AIR # simplification (no chunk border culling)
		else:
			neighbor_block = get_block(neighbor.x, neighbor.y, neighbor.z)

		if neighbor_block == VoxelData.BlockType.AIR:
			add_face(st, pos, dir, color)

func add_face(st: SurfaceTool, pos: Vector3i, dir: Vector3i, color: Color) -> void:
	var p = Vector3(pos.x, pos.y, pos.z)
	var verts: Array
	var normal := Vector3(dir.x, dir.y, dir.z)

	# Define quad corners per direction (unit cube faces)
	if dir == Vector3i(1,0,0):
		verts = [p+Vector3(1,0,0), p+Vector3(1,1,0), p+Vector3(1,1,1), p+Vector3(1,0,1)]
	elif dir == Vector3i(-1,0,0):
		verts = [p+Vector3(0,0,1), p+Vector3(0,1,1), p+Vector3(0,1,0), p+Vector3(0,0,0)]
	elif dir == Vector3i(0,1,0):
		verts = [p+Vector3(0,1,0), p+Vector3(0,1,1), p+Vector3(1,1,1), p+Vector3(1,1,0)]
	elif dir == Vector3i(0,-1,0):
		verts = [p+Vector3(0,0,1), p+Vector3(0,0,0), p+Vector3(1,0,0), p+Vector3(1,0,1)]
	elif dir == Vector3i(0,0,1):
		verts = [p+Vector3(1,0,1), p+Vector3(1,1,1), p+Vector3(0,1,1), p+Vector3(0,0,1)]
	elif dir == Vector3i(0,0,-1):
		verts = [p+Vector3(0,0,0), p+Vector3(0,1,0), p+Vector3(1,1,0), p+Vector3(1,0,0)]

	# Two triangles per quad
	st.set_normal(normal)
	st.set_color(color)
	st.add_vertex(verts[0])
	st.set_color(color)
	st.add_vertex(verts[1])
	st.set_color(color)
	st.add_vertex(verts[2])

	st.set_color(color)
	st.add_vertex(verts[0])
	st.set_color(color)
	st.add_vertex(verts[2])
	st.set_color(color)
	st.add_vertex(verts[3])
```

